"""Summarize five-seed official results with paired, seed-level differences."""
import argparse
import csv
from pathlib import Path
import numpy as np
from .common import read, write


def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--root',required=True)
    p.add_argument('--output',required=True)
    a=p.parse_args();groups={}
    for f in Path(a.root).rglob('metrics.json'):
        r=read(f)
        # Name generated by run.sh: E2_seed123_last etc.
        import re
        m=re.fullmatch(r'(E[0-4]|E3raw|C)_seed(\d+)_(last|best|epoch_\d+)',r['name'])
        if not m:continue
        method,seed,checkpoint=m.groups()
        key=(method,checkpoint,r['pamr'],r['bg_clean'],r['task'])
        groups.setdefault(key,{})
        if int(seed) in groups[key]:raise ValueError('Duplicate method/seed/task/eval record '+str(f))
        groups[key][int(seed)]=r['miou']
    result=[];rng=np.random.RandomState(123)
    for key,values in sorted(groups.items()):
        method,ckpt,pamr,bg,task=key
        vals=np.array(list(values.values()))
        row={'method':method,'checkpoint':ckpt,'pamr':pamr,'bg_clean':bg,'task':task,
             'n':len(vals),'mean':float(vals.mean()),'std_sample':float(vals.std(ddof=1)) if len(vals)>1 else None,
             'paired_vs_E0':None,'paired_vs_E2':None,'paired_vs_E3':None}
        for baseline in ('E0','E2','E3'):
            base=groups.get((baseline,ckpt,pamr,bg,task),{});seeds=sorted(set(base)&set(values))
            if seeds and baseline!=method:
                delta=np.array([values[s]-base[s] for s in seeds])
                boots=delta[rng.randint(len(delta),size=(10000,len(delta)))].mean(axis=1)
                # Exact two-sided sign-flip randomization. Five seeds cannot reach p<.05
                # for all same-sign differences (minimum 2/32=.0625).
                means=[abs(np.mean(delta*np.array([1 if (i>>j)&1 else -1 for j in range(len(delta))]))) for i in range(2**len(delta))] if len(delta)<=20 else []
                row['paired_vs_'+baseline]={'seeds':seeds,'deltas':delta.tolist(),'mean_delta':float(delta.mean()),
                    'bootstrap_ci95':np.percentile(boots,[2.5,97.5]).tolist() if len(delta)>1 else None,
                    'exact_sign_flip_p':float(np.mean(np.array(means)>=abs(delta.mean())-1e-12)) if means else None}
        result.append(row)
    if not result:raise ValueError('No matching ECCA evaluation results')
    write(a.output,result)
    csv_path=Path(a.output).with_suffix('.csv')
    with csv_path.open('w',newline='') as f:
        fields=['method','checkpoint','pamr','bg_clean','task','n','mean','std_sample']
        writer=csv.DictWriter(f,fieldnames=fields,extrasaction='ignore');writer.writeheader();writer.writerows(result)
    print(csv_path)


if __name__=='__main__':main()
